TOKEN_OWNER = 42
VALID_TOKEN = "secret-abc"

_idempotency_store = {}
_orders = {}
_next_id = [1]


def handle_create_order(req):
    body = req.get("body")
    if (
        not isinstance(body, dict)
        or not isinstance(body.get("customer_id"), int)
        or isinstance(body.get("customer_id"), bool)
        or not isinstance(body.get("amount"), int)
        or isinstance(body.get("amount"), bool)
        or body["amount"] <= 0
    ):
        return (422, {"ok": False, "error": "INVALID_BODY"})

    if req.get("token") != VALID_TOKEN:
        return (401, {"ok": False, "error": "UNAUTHENTICATED"})

    if TOKEN_OWNER != body["customer_id"]:
        return (403, {"ok": False, "error": "FORBIDDEN"})

    key = req.get("idempotency_key")
    if not key:
        return (400, {"ok": False, "error": "IDEMPOTENCY_KEY_REQUIRED"})

    if key in _idempotency_store:
        return (200, _idempotency_store[key])

    order_id = _next_id[0]
    _next_id[0] += 1
    _orders[order_id] = {"customer_id": body["customer_id"], "amount": body["amount"]}
    response_body = {"ok": True, "order_id": order_id, "amount": body["amount"]}
    _idempotency_store[key] = response_body
    return (201, response_body)


