    {"cartId": "c5", "items": [{"sku": "Z", "qty": 4, "unitPrice": 125}], "total": 500},
]

ALLOWED_TOP = {"cartId", "items", "total"}
ALLOWED_ITEM = {"sku", "qty", "unitPrice"}


class ContractError(Exception):
    pass


def validate(req):
    if set(req) - ALLOWED_TOP:
        raise ContractError("unknown field")
    items = req.get("items")
    if not isinstance(items, list) or len(items) == 0:
        raise ContractError("empty items")
    for item in items:
        if set(item) - ALLOWED_ITEM:
            raise ContractError("unknown field")
    actual = sum(item["qty"] * item["unitPrice"] for item in items)
    if actual != req.get("total"):
        raise ContractError("invariant")
    return req


for i, req in enumerate(REQUESTS):
    try:
        validate(req)
        print(f"{i}: OK")
    except ContractError as e:
        print(f"{i}: REJECT {e}")

