# CLIENT-side driver: given the flaky server's replies, decide what to do next.
MAX_ATTEMPTS = 3


def drive_payment(name, responses):
    refreshed = False
    attempts = 0
    for code in responses:
        attempts += 1
        if code in (200, 201):
            return f"{name} ok attempts={attempts}"
        if code in (403, 409, 422):
            return f"{name} rejected:{code} attempts={attempts}"
        if code == 401:
            if refreshed:
                return f"{name} auth_failed attempts={attempts}"
            refreshed = True
        if attempts >= MAX_ATTEMPTS:
            return f"{name} gave_up attempts={attempts}"
    return f"{name} gave_up attempts={attempts}"


SCENARIOS = [
    ("normal", [201]),
    ("flaky_then_ok", [503, 503, 201]),
    ("always_down", [503, 503, 503]),
    ("bad_request", [422]),
    ("token_expired", [401, 201]),
    ("really_forbidden", [401, 403]),
    ("stubborn_auth", [401, 401]),
    ("crash_then_replay", [500, 200]),
]

for scenario_name, replies in SCENARIOS:
    print(drive_payment(scenario_name, replies))

