# Ports & adapters: one storage-agnostic routine must work against two backends
# whose NATIVE apis differ. You write the uniform find/save that hides the flavor.
class SqlRepo:
    def __init__(self):
        self.rows = {}
        self.writes = 0

    def select_by_key(self, key):
        return self.rows.get(key)

    def insert(self, order, key):
        self.writes += 1
        self.rows[key] = order


class KvRepo:
    def __init__(self):
        self.store = {}
        self.writes = 0

    def get(self, key):
        return self.store.get(key)

    def put(self, key, order):
        self.writes += 1
        self.store[key] = order


def uniform_find(backend, key):
    if isinstance(backend, SqlRepo):
        return backend.select_by_key(key)
    return backend.get(key)


def uniform_save(backend, order, key):
    if isinstance(backend, SqlRepo):
        backend.insert(order, key)
    else:
        backend.put(key, order)


def place_order(backend, order, key):
    existing = uniform_find(backend, key)
    if existing is not None:
        return existing, "replay"
    uniform_save(backend, order, key)
    return order, "created"


for backend_name, backend in [("sql", SqlRepo()), ("kv", KvRepo())]:
    _, s1 = place_order(backend, "ord-1", "k1")
    _, s2 = place_order(backend, "ord-2", "k1")
    _, s3 = place_order(backend, "ord-3", "k2")
    print(f"{backend_name} {s1} {s2} {s3} writes={backend.writes}")

