# Backoff + cap: for a transient failure on a given attempt, either retry after
# an exponential-with-ceiling delay, or dead-letter once the cap is reached.
def retry_or_dlq(attempt, base, cap, max_attempts):
    if attempt >= max_attempts:
        return ("dead-letter", None)
    delay = min(base * (2 ** (attempt - 1)), cap)
    return ("retry", delay)


BASE, CAP, MAX = 1, 10, 6
for attempt in range(1, MAX + 1):
    action, delay = retry_or_dlq(attempt, BASE, CAP, MAX)
    print(f"attempt={attempt} -> {action} delay={delay}")

