class Processor:
    def __init__(self):
        self.charge_count = 0

    def charge(self, cents):
        self.charge_count += 1
        return f"ch_{self.charge_count}"


class PaymentService:
    def __init__(self, processor):
        self.processor = processor
        self._next_id = 1
        self._seen = {}

    def create(self, cents, idempotency_key):
        if not isinstance(cents, int) or isinstance(cents, bool) or cents <= 0:
            raise ValueError("cents")
        if idempotency_key in self._seen:
            return self._seen[idempotency_key]
        charge_id = self.processor.charge(cents)
        payment = {"id": self._next_id, "charge_id": charge_id, "cents": cents}
        self._next_id += 1
        self._seen[idempotency_key] = payment
        return payment


def verdict(name, ok):
    return f"{name}: {'PASS' if ok else 'FAIL'}"


def run_tests():
    results = []

    # Contract 1: rejects malformed body
    svc = PaymentService(Processor())
    try:
        svc.create(-1, "k1")
        results.append(verdict("reject_malformed", False))
    except ValueError as e:
        results.append(verdict("reject_malformed", str(e) == "cents"))

    # Contract 2: idempotent replay charges once
    proc = Processor()
    svc = PaymentService(proc)
    first = svc.create(500, "abc-123")
    second = svc.create(500, "abc-123")
    results.append(verdict("idempotent_replay", first["id"] == second["id"] and proc.charge_count == 1))

    # Contract 3: distinct keys create distinct payments
    proc = Processor()
    svc = PaymentService(proc)
    a = svc.create(100, "key-a")
    b = svc.create(100, "key-b")
    results.append(verdict("distinct_keys", a["id"] != b["id"] and proc.charge_count == 2))

    for line in results:
        print(line)


run_tests()

