import math

CAPACITY = 5
REFILL_PER_MS = 0.002

REQUESTS = [0, 100, 200, 300, 400, 500, 600, 2000, 2100]


def process(requests):
    tokens = None
    ts = None
    out = []
    for i, now in enumerate(requests):
        if tokens is None:
            tokens = float(CAPACITY)
        else:
            tokens = min(float(CAPACITY), tokens + (now - ts) * REFILL_PER_MS)
        ts = now
        if tokens < 1:
            wait = math.ceil((1 - tokens) / REFILL_PER_MS)
            out.append(f"req {i} @ {now}ms REJECT wait={wait}ms")
        else:
            tokens -= 1
            out.append(f"req {i} @ {now}ms ADMIT tokens={tokens:.2f}")
    return out


for line in process(REQUESTS):
    print(line)

