# The versioning JUDGMENT, not one upgrade seam: classify each proposed API
# change as backward-compatible or breaking for existing callers.
def classify_change(change):
    kind = change["kind"]
    if kind == "add_field":
        return "compatible" if change["optional"] else "breaking"
    if kind == "remove_field":
        return "breaking"
    if kind == "tighten_validation":
        return "breaking"
    if kind == "loosen_validation":
        return "compatible"
    return "unknown"


