    Account("acct_1", owner_id="user_a", tenant_id="tnt_1"),
    Account("acct_2", owner_id="user_b", tenant_id="tnt_1"),
    Account("acct_3", owner_id="user_a", tenant_id="tnt_2"),
]


@dataclass(frozen=True)
class Caller:
    id: str
    tenant_id: str


def authorize_transfer(account_id, caller):
    account = next(
        (a for a in ACCOUNTS
         if a.id == account_id and a.tenant_id == caller.tenant_id),
        None,
    )
    if account is None or account.owner_id != caller.id:
        return 404
    return 200


