from dataclasses import dataclass


@dataclass(frozen=True)
class Actor:
    id: str


VALID_TOKENS = {"tok_alice": Actor("user_alice"), "tok_bob": Actor("user_bob")}


def authorize(token):
    return VALID_TOKENS.get(token)


def validate(body):
    if not isinstance(body.get("amount_cents"), int):
        return "amount_cents must be int"
    if body["amount_cents"] <= 0:
        return "amount_cents must be positive"
    if body.get("currency") != "usd":
        return "currency must be usd"
    return None


_idem_store = {}


def handle_charge(idem_key, token, body):
    if not idem_key:
        return (400, "Idempotency-Key header required")
    actor = authorize(token)
    if actor is None:
        return (401, "unauthenticated")
    err = validate(body)
    if err is not None:
        return (422, err)
    store_key = (actor.id, idem_key)
    if store_key in _idem_store:
        return (200, _idem_store[store_key])
    charge_id = f"ch_{actor.id}_{idem_key}"
    _idem_store[store_key] = charge_id
    return (201, charge_id)


REQUESTS = [
    ("", "tok_alice", {"amount_cents": 500, "currency": "usd"}),
    ("idem-1", "tok_bad", {"amount_cents": 500, "currency": "usd"}),
    ("idem-1", "tok_alice", {"amount_cents": -5, "currency": "usd"}),
    ("idem-1", "tok_alice", {"amount_cents": 500, "currency": "eur"}),
    ("idem-1", "tok_alice", {"amount_cents": 500, "currency": "usd"}),
    ("idem-1", "tok_alice", {"amount_cents": 999, "currency": "usd"}),
    ("idem-1", "tok_bob", {"amount_cents": 500, "currency": "usd"}),
