RACE = [("A", "dup-key", 500), ("B", "dup-key", 500)]


def create_charge(request, store):
    body = request["body"]
    account_id = body.get("account_id")
    amount = body.get("amount")
    if (
        not isinstance(account_id, str)
        or not isinstance(amount, int)
        or isinstance(amount, bool)
        or amount <= 0
    ):
        return (422, "422 invalid")
    if request["actor"] != account_id:
        return (403, "403 forbidden")
    key = request.get("idempotency_key")
    if not isinstance(key, str) or key == "":
        return (400, "400 key required")
    if key in store:
        return (200, f"200 replayed {store[key]}")
    store[key] = amount
    return (201, f"201 created {amount}")


class ChargeStore:
    """find() and commit() are two separate steps -- exactly like two round-trips
    to Postgres. claim() is the ONLY indivisible one: it is this lab's stand-in
    for INSERT INTO idempotency(key) ... ON CONFLICT DO NOTHING."""

    def __init__(self):
        self._keys = {}
        self.rows = []

    def find(self, key):
        return self._keys.get(key)

    def claim(self, key):
        token = object()
        return self._keys.setdefault(key, token) is token

    def commit(self, key, row):
        self._keys[key] = row
        self.rows.append(row)


def charge_coro(key, amount, store):
    won = store.claim(key)
    yield
    if not won:
        return ("replayed", store.find(key))
    row = {"charge_id": len(store.rows) + 1, "amount": amount}
    store.commit(key, row)
    return ("created", row)


def run_interleaved(requests, store):
    coros = []
    for name, key, amount in requests:
        c = charge_coro(key, amount, store)
        try:
            next(c)
        except StopIteration:
            raise RuntimeError(f"{name}: coroutine returned without yielding once")
        coros.append((name, c))
    results = {}
    for name, c in coros:
        try:
            next(c)
        except StopIteration as stop:
            results[name] = stop.value
        else:
            raise RuntimeError(f"{name}: yielded more than once")
    return results


def main():
    store = {}
    for req in REQUESTS:
        status, body = create_charge(req, store)
        print(body)

    race_store = ChargeStore()
    results = run_interleaved(RACE, race_store)
    for name, _key, _amount in RACE:
        outcome, row = results[name]
        print(f"{name}: {outcome} charge={row['charge_id']}")
    print(f"charges_written: {len(race_store.rows)}")


if __name__ == "__main__":
    main()
